using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class HouseholdStorageChecks {
 static void Require(bool condition,string why){if(!condition)throw new Exception(why);}
 [MenuItem("BWVR/Verify households and storage model")]
 public static void VerifyModel(){var r=new ResourceState{wood=12,wheat=48};var field=r.Ensure("field",VillageResource.Wheat);r.Harvest(0,"field",3);Require(r.Deposit(0)==3&&r.exposedWheat==3&&r.NeedsStorage,"Overflow was lost or did not request storage");r.Consume(10,0);Require(Mathf.Abs(r.spoiled-.25f)<.001f,"Uncovered grain did not spoil");Require(!r.BuildStorage(19)&&r.wood==12,"Early construction spent wood");var saved=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(r));saved.wheat=20;Require(saved.NeedsStorage,"Committed construction abandoned as food was eaten");Require(saved.Valid()&&saved.storageWork==19,"Construction progress did not save");Require(saved.BuildStorage(1)&&saved.wood==6&&saved.storageUpgrades==1&&saved.exposedWheat==0&&saved.wheat>20,"Completed storage did not pay/shelter overflow");float spoiled=saved.spoiled;saved.Consume(20,0);Require(saved.spoiled==spoiled,"Sheltered grain spoiled");saved.storageUpgrades=4;Require(!saved.Valid(),"Unbounded storage accepted");var family=new FamilyState();Require(!family.FormHousehold(0,0,10)&&family.FormHousehold(0,1,10),"Invalid household pairing");family.bond=.9f;Require(!family.TryBirth(10,3),"Birth ignored cooldown");family.clock=300;Require(!family.TryBirth(7,3)&&family.TryBirth(10,3)&&!family.TryBirth(10,3),"Food/cooldown/exactly once birth failed");var child=family.children[0];var inherit=VillagerTraits.Inherit(family.adults[0],family.adults[1],3);Require(child.traits.boldness==inherit.boldness&&Mathf.Abs(child.traits.diligence-.6f)<=.081f,"Inherited traits not deterministic/bounded");family.clock=900;family.TryBirth(10,3);family.clock=1500;family.TryBirth(10,3);family.clock=2100;Require(!family.TryBirth(10,3)&&family.children.Length==3,"Population cap failed");var season=new SliceState{families=family,resources=r};Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(season)).Valid(),"Family/storage save invalid");child.parentA=2;Require(!season.Valid(),"Invalid parentage accepted");Require(new SliceState().Valid(),"Legacy season invalid");Debug.Log("BWVR_HOUSEHOLD_STORAGE_MODEL_PASS");}
 [MenuItem("BWVR/Verify household and storage runtime (Play mode)")]
 public static void VerifyRuntime(){var world=UnityEngine.Object.FindAnyObjectByType<VillageResources>();Require(EditorApplication.isPlaying&&world!=null,"Enter Play mode");var slice=world.GetComponentInParent<QuestSlice>();var families=slice.GetComponentInChildren<VillageFamilies>();var f=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)f.GetValue(slice);var positions=world.Gatherers.Select(a=>a.transform.position).ToArray();var test=new SliceState{developmentFocus=true};foreach(var a in world.Gatherers){a.Cancel();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}f.SetValue(slice,test);world.ResetWorld();families.ResetWorld();try{
  test.Resources.wood=12;test.Resources.wheat=48;var actor=world.Gatherers[1];actor.transform.position=world.StoreApproach;actor.GetComponent<IslandNavigator>().ResetRoute();Require(actor.TryBuildStorage()&&!world.Gatherers[2].TryBuildStorage(),"Storage builders not exclusive");actor.Tick(30,true);Require(test.Resources.storageWork==0,"Paused construction advanced");for(int i=0;i<500&&actor.Active;i++)actor.Tick(.05f,false);Require(test.Resources.storageUpgrades==1&&test.Resources.wood==6&&!actor.Active,"Native storage construction failed");world.Refresh();Require(world.transform.Find("Built storage shelf 1").gameObject.activeSelf&&!world.transform.Find("Built storage shelf 2").gameObject.activeSelf,"Capacity shelving not visible");
  test.Resources.wheat=30;Require(actor.TryBegin(world.sources.First(s=>s.kind==VillageResource.Wood&&world.Available(s))),"Cannot stage pending home visit");test.Families.visitAt=0;families.Advance(.1f,false);Require(families.Visiting,"No autonomous home visit");Require(!families.TickAdult(actor.GetComponent<VillagerRoutine>(),.1f)&&actor.Active,"Home visit stole unfinished gathering");actor.Cancel();for(int n=0;n<1200&&families.Visiting;n++){foreach(var a in world.Gatherers)families.TickAdult(a.GetComponent<VillagerRoutine>(),.1f);families.Advance(.1f,false);}Require(test.Families.together>20&&test.Families.bond>.4f,"Villagers did not share a reachable home");test.Families.bond=.7f;test.Families.together=70;test.Families.visitAt=test.Families.clock;families.Advance(.1f,false);for(int n=0;n<1200&&!test.Families.Partnered;n++){foreach(var a in world.Gatherers)families.TickAdult(a.GetComponent<VillagerRoutine>(),.1f);families.Advance(.1f,false);}Require(test.Families.Partnered,"Friends did not form household");var family=test.Families;Require(world.Gatherers[family.parentA].GetComponent<CarryItem>().home!=positions[family.parentA]&&Vector3.Distance(world.Gatherers[family.parentA].GetComponent<CarryItem>().home,world.Gatherers[family.parentB].GetComponent<CarryItem>().home)<world.Navigation.Scale*5,"Partners do not share home");family.bond=.9f;family.clock=family.nextBirth;float food=test.Resources.wheat;families.Advance(.1f,false);Require(family.children.Length==1&&families.VisibleChildren==1&&test.Resources.wheat==food-2,"Offspring did not appear/feed");float age=family.children[0].age;families.Advance(30,true);Require(family.children[0].age==age,"Paused offspring aged");var restored=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(restored.Valid(),"Runtime save invalid");f.SetValue(slice,restored);families.ResetWorld();Require(families.VisibleChildren==1,"Reload lost/duplicated child");Debug.Log("BWVR_HOUSEHOLD_STORAGE_RUNTIME_PASS");
 }finally{foreach(var a in world.Gatherers)a.Cancel();f.SetValue(slice,original);world.ResetWorld();families.ResetWorld();for(int i=0;i<world.Gatherers.Length;i++){world.Gatherers[i].transform.position=positions[i];world.Gatherers[i].GetComponent<IslandNavigator>().ResetRoute();}}}
}
}
